import * as THREE from 'three';

/**
 * MSDF digit atlas (assets/fonts/digits.png + digits.json, generated by scripts/build-sdf.mjs).
 * Glyph uv rects use three.js texture conventions (flipY: v grows upwards), so a face-local
 * rect with +y up maps onto its uv rect without mirroring.
 */

const UNDERLINE = '.';
/**
 * The 6/9 mark is a short, thick bar set well below the digit, so that rotated it cannot
 * read as a "1" (Plan 1's long thin underline could).
 * Thickness and gap are relative to the digit ink height.
 */
const UNDERLINE_THICKNESS = 0.16;
const UNDERLINE_GAP = 0.26;
/** Underline ink width, relative to the ink width of the digit above it. */
const UNDERLINE_WIDTH = 0.45;

/**
 * @param {object} json BMFont JSON written by build-sdf.mjs
 * @returns {{glyphs: Map<string, object>, distanceRange: number, base: number,
 *   scaleW: number, scaleH: number, pad: number, digitHeight: number}}
 */
export function parseAtlas(json) {
  const { scaleW, scaleH, base } = json.common;
  const distanceRange = json.distanceField.distanceRange;
  const glyphs = new Map();
  for (const c of json.chars) {
    glyphs.set(c.char, {
      u0: c.x / scaleW,
      v0: 1 - (c.y + c.height) / scaleH,
      u1: (c.x + c.width) / scaleW,
      v1: 1 - c.y / scaleH,
      w: c.width,
      h: c.height,
      xoffset: c.xoffset,
      yoffset: c.yoffset,
      xadvance: c.xadvance,
    });
  }
  // The generator pads every glyph box by half the distance range on each side.
  const pad = distanceRange / 2;
  let digitHeight = 0;
  for (const c of '0123456789') {
    const g = glyphs.get(c);
    if (g) digitHeight = Math.max(digitHeight, g.h - 2 * pad);
  }
  return { glyphs, distanceRange, base, scaleW, scaleH, pad, digitHeight };
}

/**
 * Loads digits.json and digits.png from a base URL.
 * @param {string} baseUrl folder holding the atlas, e.g. "modules/dicer/assets/fonts"
 */
export async function loadDigitAtlas(baseUrl) {
  const root = baseUrl.replace(/\/+$/, '');
  const [json, texture] = await Promise.all([
    fetch(`${root}/digits.json`).then((r) => {
      if (!r.ok) throw new Error(`dicer: cannot load ${root}/digits.json (${r.status})`);
      return r.json();
    }),
    new THREE.TextureLoader().loadAsync(`${root}/digits.png`),
  ]);
  // Distances must not be filtered across glyphs or gamma-decoded.
  texture.colorSpace = THREE.NoColorSpace;
  texture.generateMipmaps = false;
  texture.minFilter = THREE.LinearFilter;
  texture.magFilter = THREE.LinearFilter;
  texture.needsUpdate = true;
  return { ...parseAtlas(json), texture };
}

/** Pixel-space box of a glyph (y up, baseline at 0), optionally stretched. */
function boxOf(g, x0, y1, sx = 1, sy = 1, pad = 0) {
  const b = { g, x0, x1: x0 + g.w * sx, y0: y1 - g.h * sy, y1, v0: g.v0, v1: g.v1 };
  // Ink extents: the box minus its distance-field margin.
  Object.assign(b, { ix0: b.x0 + pad * sx, ix1: b.x1 - pad * sx });
  Object.assign(b, { iy0: b.y0 + pad * sy, iy1: b.y1 - pad * sy });
  return b;
}

/** Moves a box edge to y (bottom or top), trimming its uv rect to match. */
function clipY(b, edge, y) {
  const dv = (b.v1 - b.v0) / (b.y1 - b.y0);
  if (edge === 'bottom') {
    b.v0 += (y - b.y0) * dv;
    b.y0 = y;
  } else {
    b.v1 -= (b.y1 - y) * dv;
    b.y1 = y;
  }
}

/**
 * Lays out a face label (up to 2 glyphs) in face-local units, centred at the origin.
 * Each glyph is 8 floats: x0, y0, x1, y1 (face rect), u0, v0, u1, v1 (atlas rect).
 * A trailing "." is the underline mark under the preceding digit. Unused slots are zero.
 * `size` is the digit ink height in face units. Glyph rects never overlap: the shader
 * samples each glyph only inside its own rect.
 * @returns {Float32Array} length 16
 */
export function layoutLabel(label, atlas, size = 0.62) {
  const out = new Float32Array(16);
  const { pad, base, digitHeight } = atlas;
  const boxes = [];
  let pen = 0;
  for (const ch of String(label)) {
    if (boxes.length === 2) break;
    const g = atlas.glyphs.get(ch);
    if (!g) continue;
    if (ch === UNDERLINE) {
      const above = boxes[boxes.length - 1];
      if (!above) continue;
      const sx = (UNDERLINE_WIDTH * (above.ix1 - above.ix0)) / (g.w - 2 * pad);
      const sy = (UNDERLINE_THICKNESS * digitHeight) / (g.h - 2 * pad);
      const cx = (above.ix0 + above.ix1) / 2;
      const inkTop = above.iy0 - UNDERLINE_GAP * digitHeight;
      const u = boxOf(g, cx - (g.w * sx) / 2, inkTop + pad * sy, sx, sy, pad);
      // Split the margins at the middle of the ink gap (half a px apart).
      const mid = (above.iy0 + inkTop) / 2;
      if (above.y0 < mid + 0.25) clipY(above, 'bottom', mid + 0.25);
      if (u.y1 > mid - 0.25) clipY(u, 'top', mid - 0.25);
      boxes.push(u);
      continue;
    }
    let b = boxOf(g, pen + g.xoffset, base - g.yoffset, 1, 1, pad);
    const prev = boxes[boxes.length - 1];
    if (prev && b.x0 < prev.x1) {
      // Track the glyphs apart so their distance margins do not overlap.
      const shift = prev.x1 - b.x0;
      b = boxOf(g, b.x0 + shift, b.y1, 1, 1, pad);
      pen += shift;
    }
    pen += g.xadvance;
    boxes.push(b);
  }
  if (!boxes.length) return out;

  const cx = (Math.min(...boxes.map((b) => b.ix0)) + Math.max(...boxes.map((b) => b.ix1))) / 2;
  const cy = (Math.min(...boxes.map((b) => b.iy0)) + Math.max(...boxes.map((b) => b.iy1))) / 2;
  const s = size / digitHeight;
  boxes.forEach((b, i) => {
    const rect = [(b.x0 - cx) * s, (b.y0 - cy) * s, (b.x1 - cx) * s, (b.y1 - cy) * s];
    out.set([...rect, b.g.u0, b.v0, b.g.u1, b.v1], i * 8);
  });
  return out;
}
